  "source_path": "/discovery",
  "operations": {
    "post": {
      "operationId": "ConfirmationOfPayeeDiscovery_signedDiscoveryRequest",
      "summary": "Discover the LFI that will confirm the payee attributes",
      "description": "Before a Confirmation of Payee (CoP) operation takes place the TPP will need to resolve the LFI that will service the account properties request. This requirement is based on the separation of concerns implemented in the OFP, which ensures that the APIs for a given LFI are always physically separated.\n\nThe TPP will call this endpoint with the Creditor Account IBAN, which will be used to resolve the correct URL with which to make the CoP operation.",
